import { test, expect } from "@playwright/test";

const STORE_URL = process.env.STORE_URL ?? "http://localhost:4100";

test("With the coupon removed there is no discount and total = subtotal.", async ({ page }) => {
  await page.goto(new URL("/", STORE_URL).href);
  await expect(page.getByTestId("store-header")).toBeVisible();
  await page.getByTestId("add-to-cart-canvas-tote").click();
  await page.goto(new URL("/cart", STORE_URL).href);
  await expect(page.getByTestId("store-header")).toBeVisible();
  await page.getByTestId("coupon-input").fill("SAVE10");
  await page.getByTestId("apply-coupon").click();
  await page.getByTestId("remove-coupon").click();

  // Spec: Discount matches the applied coupon's rule (no coupon → no discount)
  await expect(page.getByTestId("cart-discount")).toBeHidden();
  // Spec: Total equals subtotal minus discount
  await expect(page.getByTestId("cart-total")).toHaveText("$24.00");
});
